import { MultiSelect, type MultiSelectChangeDetail } from '@absoluteui/components/multi-select';

const form = document.createElement('form');
const host = document.createElement('div');
form.append(host);
document.body.append(form);
const skills = MultiSelect.create(host, {
  label: 'Skills',
  name: 'skills',
  required: true,
  selectAll: true,
  maxSelected: 5,
  options: [
    { value: 'ts', label: 'TypeScript' },
    { value: 'sql', label: 'SQL' },
    { value: 'ux', label: 'UX research', description: 'Interviews and testing' },
  ],
  value: ['ts'],
});
skills.host.addEventListener('aui-change', (event) => {
  const { value, added, removed } = (event as CustomEvent<MultiSelectChangeDetail>).detail;
  console.log(value, added, removed);
});

import { MultiSelect, type MultiSelectOption } from '@absoluteui/components/multi-select';

const host = document.createElement('div');
document.body.append(host);
MultiSelect.create(host, {
  label: 'Reviewers',
  options: [],
  loadOptions: async (query, { signal }): Promise<MultiSelectOption[]> => {
    const response = await fetch(`/api/people?q=${encodeURIComponent(query)}`, { signal });
    const people = (await response.json()) as { id: string; name: string }[];
    return people.map((p) => ({ value: p.id, label: p.name }));
  },
});
